-- ============================================================================
-- 业务种子数据（data_initialization.sql，可选执行）
-- ----------------------------------------------------------------------------
-- 作用：灌入可选的业务示例种子，共 5 个分类：
--   01 应用        krun_autotest_project（ToolBox工具箱）
--   02 标签        krun_autotest_tag（技术测试团队 × 3）
--   03 环境字典    krun_autotest_env（UAT1/UAT2/UAT3）
--   04 环境绑定    krun_autotest_env_bind（3 环境 × app/database/file）
--   05 环境配置    krun_autotest_env_config（15 配置 × 3 环境，占位地址需按真实环境修正）
--
-- 边界：系统启动必需种子（菜单/路由/角色/部门/用户及其绑定表）由应用启动时
--       core/initializations/data_initialization.py 自动初始化，不在本文件范围。
-- 前提：表结构已由 aerich 迁移创建（uv run aerich upgrade），且应用至少启动过一次
--       （负责人 admin/tester/guest 等种子账号由启动初始化创建）。
-- 执行：mysql -h <host> -P <port> -u <user> -p <database> < backend/scripts/data_initialization.sql
-- 幂等：全部语句按自然键 NOT EXISTS 防重，可重复执行；不覆盖已有数据。
-- 顺序：分类编号即依赖顺序（应用→标签/环境绑定→环境配置）。
-- 说明：是否执行由使用方自行决定；不执行不影响系统启动与登录，
-- ============================================================================

SET NAMES utf8mb4;

-- ----------------------------------------------------------------------------
-- 01 应用（krun_autotest_project）：平台默认应用 ToolBox工具箱
-- ----------------------------------------------------------------------------
